input.command:
cat > variables.tf <<'EOF'
variable "github_repository" {
  type        = string
  description = "GitHub repository, as owner/name, whose workflows may assume the CI roles. The role trust policies match this value exactly in the OIDC subject claim."
  default     = "platform/ingest"

  validation {
    condition     = can(regex("^[A-Za-z0-9._-]+/[A-Za-z0-9._-]+$", var.github_repository))
    error_message = "github_repository must be in owner/name form with no wildcards."
  }
}

variable "apply_branch" {
  type        = string
  description = "Branch whose workflow runs may assume the apply role. Runs from any other ref, including pull requests, cannot."
  default     = "main"
}

variable "state_bucket" {
  type        = string
  description = "Name of the S3 bucket that holds this configuration's remote state, as set in the backend block. The CI roles get access to the state key of this configuration only."
  default     = "ingest-terraform-state"
}

variable "state_key" {
  type        = string
  description = "Object key of this configuration's state file, as set in the backend block."
  default     = "ingest/terraform.tfstate"
}
EOF
cat > ci.tf <<'EOF'
data "aws_caller_identity" "current" {}

locals {
  state_object_arn = "arn:aws:s3:::${var.state_bucket}/${var.state_key}"
  lock_object_arn  = "arn:aws:s3:::${var.state_bucket}/${var.state_key}.tflock"
  state_bucket_arn = "arn:aws:s3:::${var.state_bucket}"
}

# GitHub Actions exchanges a per-run OIDC token for short-lived credentials, so no static AWS
# key is stored in the repository or the CI secret store. An account can hold one provider per
# issuer URL; import an existing one instead of creating a second.
resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repository}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${var.github_repository}:ref:refs/heads/${var.apply_branch}"]
    }
  }
}

# Plan role: read access to refresh the managed resources, plus the state read and the lock
# object write that `use_lockfile` needs. It cannot change any managed resource.
resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  description          = "Assumed by pull request workflows of the ingest repository to run terraform plan."
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

data "aws_iam_policy_document" "plan" {
  statement {
    sid       = "ReadLandingBucket"
    actions   = ["s3:GetBucket*", "s3:GetAccelerateConfiguration", "s3:GetEncryptionConfiguration", "s3:GetLifecycleConfiguration", "s3:GetReplicationConfiguration", "s3:GetObjectLockConfiguration", "s3:GetAnalyticsConfiguration", "s3:GetInventoryConfiguration", "s3:GetMetricsConfiguration", "s3:GetIntelligentTieringConfiguration", "s3:ListBucket"]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid       = "ReadEventsQueue"
    actions   = ["sqs:GetQueueAttributes", "sqs:ListQueueTags"]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ReadCheckpointsTable"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }

  statement {
    sid       = "ReadCiRoleState"
    actions   = ["sts:GetCallerIdentity"]
    resources = ["*"]
  }

  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = [local.state_object_arn]
  }

  statement {
    sid       = "ListStateBucket"
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]

    condition {
      test     = "StringEquals"
      variable = "s3:prefix"
      values   = [var.state_key, "${var.state_key}.tflock"]
    }
  }

  statement {
    sid       = "HoldStateLock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [local.lock_object_arn]
  }

  statement {
    sid = "ReadCiIamForRefresh"
    actions = [
      "iam:GetOpenIDConnectProvider",
      "iam:GetRole",
      "iam:GetRolePolicy",
      "iam:ListRolePolicies",
      "iam:ListAttachedRolePolicies",
    ]
    resources = [
      aws_iam_openid_connect_provider.github.arn,
      aws_iam_role.ci_plan.arn,
      aws_iam_role.ci_apply.arn,
    ]
  }
}

resource "aws_iam_role_policy" "ci_plan" {
  name   = "terraform-plan"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.plan.json
}

# Apply role: write access to the three managed resources and the CI identity objects in this
# file, and to this configuration's state key. Only runs from the protected branch can assume it.
resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  description          = "Assumed by workflow runs on the protected branch of the ingest repository to run terraform apply."
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

data "aws_iam_policy_document" "apply" {
  statement {
    sid       = "ManageLandingBucket"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid       = "ManageEventsQueue"
    actions   = ["sqs:*"]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid       = "ManageCheckpointsTable"
    actions   = ["dynamodb:*"]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }

  statement {
    sid       = "ReadCallerIdentity"
    actions   = ["sts:GetCallerIdentity"]
    resources = ["*"]
  }

  statement {
    sid       = "ReadWriteState"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = [local.state_object_arn, local.lock_object_arn]
  }

  statement {
    sid       = "ListStateBucket"
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]

    condition {
      test     = "StringEquals"
      variable = "s3:prefix"
      values   = [var.state_key, "${var.state_key}.tflock"]
    }
  }
}

resource "aws_iam_role_policy" "ci_apply" {
  name   = "terraform-apply"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.apply.json
}
EOF
echo

